
.agent-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  font-family: var(--font-title);
  font-size: 12px;
  font-weight: bold;
  color: var(--c-text);
  margin-bottom: 6px;
  padding-bottom: 3px;
  border-bottom: 1px dashed var(--c-border-light);
}

.title-marker {
  color: var(--c-accent-green-bright);
  margin-right: 4px;
}

.cover-block,
.progress-block {
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--c-border-light);
  border-left: 3px solid var(--c-accent-green);
  padding: 8px 10px;
}

.cover-text,
.progress-text {
  font-size: 12px;
  color: var(--c-text);
  line-height: 1.5;
}

.intel-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.intel-item {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--c-border-light);
  padding: 7px 10px;
  position: relative;
}

.intel-item::before {
  content: '▸';
  position: absolute;
  left: -1px;
  top: 50%;
  transform: translate(-50%, -50%);
  color: var(--c-accent-green-bright);
  font-size: 10px;
}

.intel-name {
  font-size: 11px;
  font-weight: bold;
  color: var(--c-accent-green-bright);
  margin-bottom: 2px;
}

.intel-content {
  font-size: 11px;
  color: var(--c-text-dim);
  line-height: 1.4;
}

.empty-intel {
  text-align: center;
  color: var(--c-text-dim);
  padding: 14px;
  font-size: 12px;
  font-style: italic;
  background: rgba(0, 0, 0, 0.15);
  border: 1px dashed var(--c-border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.empty-icon {
  font-size: 14px;
}

.warning-box {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 10px;
  background: rgba(139, 58, 58, 0.15);
  border: 1px solid var(--c-accent-red);
  font-size: 10px;
  color: var(--c-accent-red-bright);
  line-height: 1.4;
}

.warning-icon {
  flex-shrink: 0;
  margin-top: 1px;
}
