
.prisoner-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  font-family: var(--font-title);
  font-size: 12px;
  font-weight: bold;
  color: var(--c-text);
  margin-bottom: 6px;
  padding-bottom: 3px;
  border-bottom: 1px dashed var(--c-border-light);
}

.title-marker {
  color: var(--c-accent-red-bright);
  margin-right: 4px;
}

.info-block {
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--c-border-light);
  padding: 7px 10px;
}

.info-row {
  display: flex;
  gap: 8px;
  font-size: 12px;
  line-height: 1.5;
}

.info-label {
  color: var(--c-text-dim);
  flex-shrink: 0;
  min-width: 36px;
  font-size: 11px;
}

.info-content {
  color: var(--c-text);
}

/* 数据表格 */
.data-table {
  border: 1px solid var(--c-border-light);
  background: rgba(0, 0, 0, 0.2);
}

.data-row {
  display: flex;
  align-items: center;
  padding: 4px 10px;
  border-bottom: 1px solid rgba(90, 74, 58, 0.2);
  font-size: 11px;
  gap: 8px;
}

.data-row:last-child {
  border-bottom: none;
}

.data-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.data-label {
  width: 68px;
  flex-shrink: 0;
  color: var(--c-text-dim);
  letter-spacing: 2px;
  font-size: 11px;
}

.data-value {
  width: 52px;
  flex-shrink: 0;
  font-weight: bold;
  font-size: 12px;
  text-align: right;
}

.data-note {
  flex: 1;
  color: var(--c-text-dim);
  font-size: 10px;
  font-style: italic;
  text-align: right;
}

.val-safe {
  color: var(--c-accent-green-bright);
}
.val-warn {
  color: var(--c-accent-amber);
}
.val-danger {
  color: var(--c-accent-red-bright);
}
.val-loyalty {
  color: var(--c-accent-red-bright);
  text-shadow: 0 0 4px rgba(196, 80, 80, 0.3);
}
.val-positive {
  color: var(--c-accent-green-bright);
}
.val-alert {
  color: var(--c-accent-amber);
}
