
.status-bars {
  padding: 8px 12px;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-bg-section);
}

.bars-title {
  font-family: var(--font-title);
  font-size: 12px;
  font-weight: bold;
  color: var(--c-text);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.bars-icon {
  color: var(--c-accent-red-bright);
}

.spirit-badge,
.attitude-badge {
  font-size: 10px;
  padding: 1px 6px;
  font-family: var(--font-main);
  letter-spacing: 1px;
}

.spirit-badge {
  background: var(--c-accent-red);
  color: var(--c-text-bright);
}

.attitude-badge {
  background: var(--c-accent-blue);
  color: var(--c-text-bright);
}

.bars-grid {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  font-size: 11px;
  color: var(--c-text-dim);
  width: 72px;
  flex-shrink: 0;
  letter-spacing: 1px;
}

.bar-track {
  flex: 1;
  height: 8px;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid var(--c-border-light);
  position: relative;
  overflow: hidden;
}

.bar-fill {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  transition: width 0.4s ease;
}

.bar-fill.safe {
  background: var(--c-accent-green);
}
.bar-fill.warn {
  background: var(--c-accent-amber);
}
.bar-fill.danger {
  background: var(--c-accent-red-bright);
}
.bar-fill.loyalty {
  background: linear-gradient(90deg, var(--c-accent-red), #d4444a);
}
.bar-fill.positive {
  background: var(--c-accent-green-bright);
}
.bar-fill.neutral {
  background: var(--c-accent-amber);
}
.bar-fill.hostile {
  background: var(--c-accent-red);
}
.bar-fill.alert-high {
  background: var(--c-accent-amber);
  box-shadow: 0 0 4px var(--c-accent-amber);
}

.bar-value {
  font-size: 11px;
  font-weight: bold;
  width: 40px;
  text-align: right;
  flex-shrink: 0;
}

.bar-value.safe {
  color: var(--c-accent-green-bright);
}
.bar-value.warn {
  color: var(--c-accent-amber);
}
.bar-value.danger {
  color: var(--c-accent-red-bright);
}
.bar-value.loyalty {
  color: var(--c-accent-red-bright);
}
.bar-value.positive {
  color: var(--c-accent-green-bright);
}
.bar-value.neutral {
  color: var(--c-accent-amber);
}
.bar-value.hostile {
  color: var(--c-accent-red-bright);
}
.bar-value.alert-high {
  color: var(--c-accent-amber);
}

@media (max-width: 500px) {
  .bar-label {
    width: 60px;
    font-size: 10px;
  }
}
